例 1：归纳证明，调用 Lean 库的 List.reverse_reverse

fn rev(xs: List<Nat>) -> List<Nat> {
  match xs {
    List::nil => [],
    List::cons(x, rest) => rev(rest) ++ [x]
  }
}

theorem rev_is_reverse(xs: List<Nat>): rev(xs) = List::reverse(xs) by {
  induction xs with
  | nil => rfl
  | cons x rest ih => rw [rev, ih, List.reverse_cons]
}

